from typing import List

def countNiceSubarrays(arr: List[int]) -> int:
    def atMost(arr, k):
        res = i = 0
        for j in range(len(arr)):
            k -= arr[j] % 2
            while k < 0:
                k += arr[i] % 2
                i += 1
            res += j - i + 1
        return res

    return atMost(arr, 1) - atMost(arr, 0)

