def shortest_path(environment: Environment, start: Tuple[int, int], target: Tuple[int, int], direction: Action) -> List[Tuple[int, int]]:
    def is_valid_move(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != 1

    def get_new_position(pos, action):
        return pos[0] + action.value[0], pos[1] + action.value[1]

    grid = [[0 for _ in range(10)] for _ in range(10)]  # Assuming a 10x10 grid
    for obstacle in environment.obstacles:
        grid[obstacle.vector[0]][obstacle.vector[1]] = 1

    q = queue.Queue()
    q.put((start, []))
    visited = set()

    while not q.empty():
        current, path = q.get()
        if current == target:
            return path
        if current in visited:
            continue
        visited.add(current)

        for action in Action:
            new_pos = get_new_position(current, action)
            if is_valid_move(new_pos[0], new_pos[1]):
                q.put((new_pos, path + [action]))

    return []

