    max_x, max_y = grid_size - 1, grid_size - 1

    for command in movement_commands:
        if command == 'U' and y < max_y:
            y += 1
        elif command == 'D' and y > 0:
            y -= 1
        elif command == 'L' and x > 0:
            x -= 1
        elif command == 'R' and x < max_x:
            x += 1

    return f"({x}, {y})"

