class Node:
    def __init__(self, tag, attrs, children):
        self.tag = tag
        self.attrs = attrs
        self.children = children

def print_tree(keyed_node, depth=0):
    if isinstance(keyed_node.node, Node):
        print("    " * depth + keyed_node.node.tag)
        for attr, value in keyed_node.node.attrs.items():
            print("    " * (depth + 1) + f"{attr}: {value}")
        for child in keyed_node.node.children:
            if isinstance(child, Node):
                print_tree(KeyedNode(None, child), depth + 1)
            else:
                print("    " * (depth + 1) + child)
    else:
        print_tree(keyed_node.node, depth)

