def in_place_scaling(values: List[float], vmin: float, vmax: float) -> None:
    if (vmax - vmin) == 0:
        raise TypeError("Can only do in-place scaling for floating-point arrays")

    for i in range(len(values)):
        values[i] -= vmin

    if (vmax - vmin) != 0:
        for i in range(len(values)):
            values[i] /= (vmax - vmin)

