class KeyValueStringHandler:
    def __init__(self):
        self.key_value_pairs = {}

    def parse_string(self, input_string):
        pairs = input_string.split(',')
        for pair in pairs:
            key, value = pair.split('=')
            if '{' in value and '}' in value:
                nested_key_value = value.strip('{}').split(',')
                nested_dict = {}
                for nested_pair in nested_key_value:
                    nested_key, nested_value = nested_pair.split('=')
                    nested_dict[nested_key] = nested_value
                self.key_value_pairs[key] = nested_dict
            else:
                self.key_value_pairs[key] = value

    def to_string(self):
        result = []
        for key, value in self.key_value_pairs.items():
            if isinstance(value, dict):
                nested_string = ','.join([f"{k}={v}" for k, v in value.items()])
                result.append(f"{key}={{{nested_string}}}")
            else:
                result.append(f"{key}={value}")
        return ','.join(result)

# Test case
class TestKeyValueStringHandler(unittest.TestCase):
