import re

def process_regex(regex: str) -> str:
    IS_PROPERTY_RE = re.compile(r'^\w+$')

    processed_regex = ''
    escape = False
    in_repl = False
    repl = ''

    for c in regex:
        if escape:
            processed_regex = processed_regex + '\\' + c
            escape = False
        else:
            if c == '\\':
                escape = True
            elif c == '{':
                in_repl = True
                repl = ''
            elif c == '}':
                in_repl = False
                if IS_PROPERTY_RE.match(repl):
                    # Replace value
                    processed_regex = processed_regex + '(?P<{}>{})'.format(repl, util.regex_for_property(repl))
                else:
                    processed_regex = processed_regex + '{' + repl + '}'
            elif in_repl:
                repl = repl + c
            else:
                processed_regex = processed_regex + c

    return processed_regex

