import UIKit

func calculatePathLength(_ path: UIBezierPath) -> Double {
    var length: Double = 0.0
    var previousPoint: CGPoint?

    for i in 0 ..< path.elementCount {
        var points = [CGPoint](repeating: .zero, count: 3)
        let type = path.element(at: i, associatedPoints: &points)

        if type == .moveTo {
            previousPoint = points[0]
        } else if type == .lineTo {
            if let previous = previousPoint {
                length += Double(hypot(points[0].x - previous.x, points[0].y - previous.y))
                previousPoint = points[0]
            }
        } else if type == .curveTo {
            if let previous = previousPoint {
                length += Double(hypot(points[2].x - previous.x, points[2].y - previous.y))
                previousPoint = points[2]
            }
        }
    }

    return length
}

