import numpy as np
from scipy import ndimage

def segment_image(image, ms_param):
    # Compute gradients using Sobel filter
    gradient_x = ndimage.sobel(image, axis=1, mode='constant')
    gradient_y = ndimage.sobel(image, axis=0, mode='constant')
    gradient_magnitude = np.sqrt(gradient_x**2 + gradient_y**2)

    # Initialize labels for each pixel
    labels = np.zeros_like(image, dtype=int)
    current_label = 1

    # Iterate through each pixel and perform segmentation
    for i in range(image.shape[0]):
        for j in range(image.shape[1]):
            if i > 0 and j > 0:
                if gradient_magnitude[i, j] > ms_param * (np.mean(gradient_magnitude[i-1:i+1, j-1:j+1]) + np.std(gradient_magnitude[i-1:i+1, j-1:j+1])):
                    labels[i, j] = current_label
                else:
                    labels[i, j] = labels[i-1, j]
            elif i > 0:
                if gradient_magnitude[i, j] > ms_param * (np.mean(gradient_magnitude[i-1:i+1, j]) + np.std(gradient_magnitude[i-1:i+1, j])):
                    labels[i, j] = current_label
                else:
                    labels[i, j] = labels[i-1, j]
            elif j > 0:
                if gradient_magnitude[i, j] > ms_param * (np.mean(gradient_magnitude[i, j-1:j+1]) + np.std(gradient_magnitude[i, j-1:j+1])):
                    labels[i, j] = current_label
                else:
                    labels[i, j] = labels[i, j-1]
            else:
                labels[i, j] = current_label
                current_label += 1

    return labels

