    if timer_name in timers and timers[timer_name]['running']:
        current_time = time.time()
        for interval, callback in timers[timer_name]['callbacks']:
            if current_time - timers[timer_name]['start_time'] >= interval:
                callback()
                timers[timer_name]['start_time'] = current_time

