import math

def calculate_angle(coords, atom1, atom2, atom3):
    def calculate_vector(coord1, coord2):
        return [coord2[0] - coord1[0], coord2[1] - coord1[1], coord2[2] - coord1[2]]

    def dot_product(v1, v2):
        return sum((a * b) for a, b in zip(v1, v2))

    def magnitude(v):
        return math.sqrt(sum(a**2 for a in v))

    vector1 = calculate_vector(coords[atom2], coords[atom1])
    vector2 = calculate_vector(coords[atom2], coords[atom3])

    dot_product_value = dot_product(vector1, vector2)
    magnitude_product = magnitude(vector1) * magnitude(vector2)

    angle_in_radians = math.acos(dot_product_value / magnitude_product)
    angle_in_degrees = math.degrees(angle_in_radians)
    return angle_in_degrees

